// Turn what the agent heard into clean data. The agent sometimes passes a phone number
// as words ("zero five nine…" or "صفر خمسة تسعة…") and spells emails out loud.
const input = $input.first().json;
const DIGITS = { "٠": 0, "١": 1, "٢": 2, "٣": 3, "٤": 4, "٥": 5, "٦": 6, "٧": 7, "٨": 8, "٩": 9, "۰": 0, "۱": 1, "۲": 2, "۳": 3, "۴": 4, "۵": 5, "۶": 6, "۷": 7, "۸": 8, "۹": 9 };
const WORDS = {
  zero: 0, oh: 0, o: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9,
  "صفر": 0, "زيرو": 0, "واحد": 1, "وحدة": 1, "اثنين": 2, "اتنين": 2, "إثنين": 2, "ثنين": 2, "اثنان": 2,
  "ثلاثة": 3, "ثلاث": 3, "تلاتة": 3, "تلات": 3, "أربعة": 4, "اربعة": 4, "أربع": 4, "اربع": 4,
  "خمسة": 5, "خمس": 5, "ستة": 6, "ست": 6, "سبعة": 7, "سبع": 7,
  "ثمانية": 8, "تمانية": 8, "ثمان": 8, "تمن": 8, "تسعة": 9, "تسع": 9,
};
const REPEAT = { double: 2, triple: 3, "دبل": 2 };

function toDigits(raw) {
  let text = String(raw || "").replace(/[٠-٩۰-۹]/g, (d) => DIGITS[d]).toLowerCase();
  const plus = /^\s*(\+|00)/.test(text) ? "+" : "";
  let out = "";
  let repeat = 1;
  for (let token of text.split(/[\s,.\-–_()\/،]+/)) {
    if (!token) continue;
    if (/^\d+$/.test(token.replace("+", ""))) { out += token.replace("+", ""); repeat = 1; continue; }
    if (token.length > 1 && token.startsWith("و") && WORDS[token.slice(1)] !== undefined) token = token.slice(1);
    if (REPEAT[token]) { repeat = REPEAT[token]; continue; }
    if (WORDS[token] !== undefined) { out += String(WORDS[token]).repeat(repeat); repeat = 1; }
  }
  if (plus && out.startsWith("00")) out = out.slice(2);
  return plus + out;
}

function cleanEmail(raw) {
  const e = String(raw || "").trim().toLowerCase()
    .replace(/\s+(at|ات)\s+/g, "@").replace(/\s+(dot|دوت|نقطة)\s+/g, ".")
    .replace(/\s+/g, "").replace(/\.$/, "");
  return e;
}

const phone = toDigits(input.phone);
const local = phone.replace("+", "");
const phoneOk = phone.startsWith("+") ? local.length >= 10 && local.length <= 15 : local.length === 9 || local.length === 10;
const email = cleanEmail(input.email);
const emailOk = email === "" || /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(email);

return [{
  json: {
    date: $now.setZone("Asia/Hebron").toFormat("yyyy-LL-dd HH:mm"),
    name: String(input.name || "").trim(),
    phone,
    phone_heard: String(input.phone || "").trim(),
    phone_ok: phoneOk,
    email,
    email_ok: emailOk,
    request: String(input.request || "").trim(),
    language: input.language === "en" ? "en" : "ar",
  },
}];

// Google Sheets failed. Keep going: Tala still gets the lead on Telegram.
const err = $json.error;
const message = typeof err === "string" ? err : err?.message || "unknown error";
return [{ json: { ...$('Clean the lead').first().json, saved: false, save_error: message } }];

// One message Tala can act on from her phone, with the save status in it.
const l = $input.first().json;
const heardDiffers = l.phone_heard && l.phone_heard.replace(/\D/g, "") !== l.phone.replace(/\D/g, "");
const lines = [
  "📞 New lead from the voice agent",
  "",
  `👤 ${l.name || "—"}`,
  `📱 ${l.phone}${heardDiffers ? `  (heard: ${l.phone_heard})` : ""}`,
  `✉️ ${l.email || "—"}${l.email_ok ? "" : "  ⚠️ looks wrong, check it"}`,
  `💬 ${l.request || "—"}`,
  `🌐 ${l.language === "en" ? "English" : "Arabic"} · 🕒 ${l.date}`,
  "",
  l.saved ? "✅ Saved to the Leads sheet" : `⚠️ NOT saved to the sheet (${l.save_error}). Add it by hand.`,
];
return [{ json: { ...l, text: lines.join("\n") } }];

// What book_call returns to the agent. It tells the agent exactly what it may promise.
const lead = $('Write the Telegram card').first().json;
const notified = !$json.error;
const reached = lead.saved || notified;
return [{
  json: {
    saved: lead.saved,
    notified_tala: notified,
    phone: lead.phone,
    say_to_caller: reached
      ? "Tell the caller their details reached Tala and she will contact them soon."
      : "Apologise: a technical problem stopped the details from reaching Tala. Ask them to call again later. Do not promise that Tala will contact them.",
  },
}];

// The number is too short or too long to be real. Nothing is saved; the agent asks again.
const l = $input.first().json;
const n = l.phone.replace("+", "").length;
return [{
  json: {
    saved: false,
    notified_tala: false,
    phone_heard: l.phone_heard,
    say_to_caller: `The phone number came through as "${l.phone || "nothing"}" (${n} digits), which is not a complete number. Ask the caller to repeat it digit by digit, read it back, then call book_call again. Nothing was saved yet.`,
  },
}];
